#!/bin/sh
set -eu
echo PRUEBA_ALMACENAMIENTO_REAL
case "${1:-all}" in all|c12-a|c12-b|c12-c) ;; *) exit 2;; esac
if test "${1:-all}" = all || test "${1:-all}" = c12-c; then
if test -z "$(kubectl get ns local-path-storage --ignore-not-found -o name)"; then
echo "Importar la imagen real del aprovisionador"
if ! ctr -n k8s.io images ls -q | grep -qx docker.io/s2ktux/local-path-lab:0.0.34; then gzip -dc /mnt/kube-client/images/curso.tar.gz | ctr -n k8s.io images import --no-unpack --platform=linux/386 -; fi
echo "Enviar el manifiesto verificado de almacenamiento"
: > /tmp/curso-local-path.yaml.upload.gz
echo "Enviar el manifiesto verificado de almacenamiento"
printf '%s' '' | base64 -d >> /tmp/curso-local-path.yaml.upload.gz
echo "Enviar el manifiesto verificado de almacenamiento"
printf '%s' 'wSx+023vkdqY3Mc9pV2v+5hXV7Td863xK6x9K2eM87O7iuzXX3oplz27Ci0fHMJQhPGxzrhBOEdnFxcXCGsU//ZxcjPvX9/G5aihJlOf5QmOTI6wWTTNVyA0mKnKki3Nxd5Jq6xeFCo/VVnnTAvFDt6wrpTqg0sbrgx325LJYW7ZrXWQ43JyMMMdZ1T8RyZNY7PWPhm3a6wNWFuYHz/RcHcq0dMESwu7TdUjOU/eXiRnOC+saKp8d2z9CyiZv3sbEAAA' | base64 -d >> /tmp/curso-local-path.yaml.upload.gz
echo "Enviar el manifiesto verificado de almacenamiento"
gzip -dc /tmp/curso-local-path.yaml.upload.gz > /tmp/curso-local-path.yaml && rm -f /tmp/curso-local-path.yaml.upload.gz
echo "Activar el aprovisionador local"
ns=$(kubectl get namespace local-path-storage --ignore-not-found -o name); test -z "$ns"; for target in clusterrole/local-path-provisioner-role clusterrolebinding/local-path-provisioner-bind storageclass/local-path; do existing=$(kubectl get "$target" --ignore-not-found -o name); test -z "$existing"; done; kubectl apply --validate=strict --request-timeout=120s -f /tmp/curso-local-path.yaml && kubectl -n local-path-storage rollout status deployment/local-path-provisioner --timeout=240s
fi
fi
if test "${1:-all}" = all || test "${1:-all}" = c12-a; then
echo INICIO_c12-a
kubectl get --raw=/readyz --request-timeout=20s
kubectl wait --for=condition=Ready node/cka-w1 --timeout=120s
test -z "$(kubectl get namespace p12a --ignore-not-found -o name)"
kubectl create namespace p12a
kubectl -n p12a wait --for=create serviceaccount/default --timeout=90s
printf '%s\n' '{"apiVersion":"v1","kind":"Pod","metadata":{"name":"temporal","namespace":"p12a","labels":{"app":"temporal"}},"spec":{"terminationGracePeriodSeconds":1,"containers":[{"name":"app","image":"busybox:1.37.0-musl","imagePullPolicy":"Never","command":["sleep","3600"],"volumeMounts":[{"name":"datos","mountPath":"/datos"}]}],"volumes":[{"name":"datos","emptyDir":{}}]}}' | kubectl apply -f -
kubectl -n p12a wait --for=condition=Ready pod/temporal --timeout=180s
kubectl -n p12a exec temporal -- sh -c 'echo TEMPORAL > /datos/nota.txt'
kubectl -n p12a exec temporal -- cat /datos/nota.txt
object=$(kubectl -n p12a get pod temporal -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e 'any(.status.conditions[]?; .type=="Ready" and .status=="True") and any(.spec.volumes[]; .name=="datos" and .emptyDir!=null) and any(.spec.containers[]; .image=="busybox:1.37.0-musl" and any(.volumeMounts[]?; .name=="datos" and .mountPath=="/datos"))' && kubectl -n p12a exec temporal -- grep -qx TEMPORAL /datos/nota.txt
echo POSITIVO_c12-a
kubectl -n p12a delete pod temporal --wait=true --timeout=90s
kubectl get --raw=/readyz --request-timeout=20s
if (set -eu; object=$(kubectl -n p12a get pod temporal -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e 'any(.status.conditions[]?; .type=="Ready" and .status=="True") and any(.spec.volumes[]; .name=="datos" and .emptyDir!=null) and any(.spec.containers[]; .image=="busybox:1.37.0-musl" and any(.volumeMounts[]?; .name=="datos" and .mountPath=="/datos"))' && kubectl -n p12a exec temporal -- grep -qx TEMPORAL /datos/nota.txt); then echo ERROR_ACEPTO_INCOMPLETO; exit 1; fi
echo NEGATIVO_c12-a
kubectl delete namespace p12a --ignore-not-found --wait=true --timeout=120s
fi
if test "${1:-all}" = all || test "${1:-all}" = c12-b; then
echo INICIO_c12-b
kubectl get --raw=/readyz --request-timeout=20s
kubectl wait --for=condition=Ready node/cka-w1 --timeout=120s
test -z "$(kubectl get namespace p12b --ignore-not-found -o name)"
kubectl create namespace p12b
kubectl -n p12b wait --for=create serviceaccount/default --timeout=90s
test -z "$(kubectl get pv pv-p12b --ignore-not-found -o name)"
: > /tmp/p12b-pv.yaml
printf '%s' '' | base64 -d >> /tmp/p12b-pv.yaml
install -m 644 /tmp/p12b-pv.yaml /root/p12b-pv.yaml
printf '%s\n' '{"apiVersion":"v1","kind":"PersistentVolume","metadata":{"name":"pv-p12b","labels":{"ejercicio":"p12b"}},"spec":{"capacity":{"storage":"32Mi"},"accessModes":["ReadWriteOnce"],"storageClassName":"curso-manual","persistentVolumeReclaimPolicy":"Retain","hostPath":{"path":"/var/lib/curso-pv/p12b","type":"DirectoryOrCreate"},"nodeAffinity":{"required":{"nodeSelectorTerms":[{"matchExpressions":[{"key":"kubernetes.io/hostname","operator":"In","values":["cka-w1"]}]}]}}}}' | kubectl apply -f -
printf '%s\n' '{"apiVersion":"v1","kind":"PersistentVolumeClaim","metadata":{"name":"datos","namespace":"p12b"},"spec":{"storageClassName":"curso-manual","accessModes":["ReadWriteOnce"],"resources":{"requests":{"storage":"16Mi"}},"selector":{"matchLabels":{"ejercicio":"p12b"}}}}' | kubectl apply -f -
printf '%s\n' '{"apiVersion":"v1","kind":"Pod","metadata":{"name":"escritor","namespace":"p12b","labels":{"app":"escritor"}},"spec":{"terminationGracePeriodSeconds":1,"containers":[{"name":"app","image":"busybox:1.37.0-musl","imagePullPolicy":"Never","command":["sleep","3600"],"volumeMounts":[{"name":"datos","mountPath":"/datos"}]}],"volumes":[{"name":"datos","persistentVolumeClaim":{"claimName":"datos"}}]}}' | kubectl apply -f -
kubectl -n p12b wait --for=condition=Ready pod/escritor --timeout=180s
kubectl -n p12b exec escritor -- sh -c 'echo PERSISTENTE > /datos/mensaje.txt'
kubectl -n p12b delete pod escritor --wait=true --timeout=90s
printf '%s\n' '{"apiVersion":"v1","kind":"Pod","metadata":{"name":"lector","namespace":"p12b","labels":{"app":"lector"}},"spec":{"terminationGracePeriodSeconds":1,"containers":[{"name":"app","image":"busybox:1.37.0-musl","imagePullPolicy":"Never","command":["sleep","3600"],"volumeMounts":[{"name":"datos","mountPath":"/datos"}]}],"volumes":[{"name":"datos","persistentVolumeClaim":{"claimName":"datos"}}]}}' | kubectl apply -f -
kubectl -n p12b wait --for=condition=Ready pod/lector --timeout=180s
kubectl -n p12b exec lector -- cat /datos/mensaje.txt
object=$(kubectl -n p12b get pv pv-p12b -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e 'def cantidad: ((tostring|capture("^(?<n>[-+]?(?:[0-9]+(?:[.][0-9]*)?|[.][0-9]+)(?:[eE][-+]?[0-9]+)?)(?<u>Ki|Mi|Gi|Ti|Pi|Ei|[numkKMGTPE]?)$"))//{n:"-1",u:""}) as $q | ($q.n|sub("^[+]";"")|sub("^[.]";"0.")|sub("^-[.]";"-0.")|tonumber)*({"":1,n:1e-9,u:1e-6,m:0.001,k:1000,K:1000,M:1e6,G:1e9,T:1e12,P:1e15,E:1e18,Ki:1024,Mi:1048576,Gi:1073741824,Ti:1099511627776,Pi:1125899906842624,Ei:1152921504606846976}[$q.u]); def equivale($n): ((cantidad-$n)|fabs)<=((($n|fabs)+1)*1e-12); .status.phase=="Bound" and (.spec.capacity.storage|equivale(33554432)) and .spec.persistentVolumeReclaimPolicy=="Retain" and .spec.claimRef.namespace=="p12b" and .spec.claimRef.name=="datos"' && object=$(kubectl -n p12b get pvc datos -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e 'def cantidad: ((tostring|capture("^(?<n>[-+]?(?:[0-9]+(?:[.][0-9]*)?|[.][0-9]+)(?:[eE][-+]?[0-9]+)?)(?<u>Ki|Mi|Gi|Ti|Pi|Ei|[numkKMGTPE]?)$"))//{n:"-1",u:""}) as $q | ($q.n|sub("^[+]";"")|sub("^[.]";"0.")|sub("^-[.]";"-0.")|tonumber)*({"":1,n:1e-9,u:1e-6,m:0.001,k:1000,K:1000,M:1e6,G:1e9,T:1e12,P:1e15,E:1e18,Ki:1024,Mi:1048576,Gi:1073741824,Ti:1099511627776,Pi:1125899906842624,Ei:1152921504606846976}[$q.u]); def equivale($n): ((cantidad-$n)|fabs)<=((($n|fabs)+1)*1e-12); .status.phase=="Bound" and (.spec.resources.requests.storage|equivale(16777216)) and .spec.accessModes==["ReadWriteOnce"]' && object=$(kubectl -n p12b get pvc datos -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e '.spec.volumeName=="pv-p12b" and .spec.storageClassName=="curso-manual" and .spec.selector.matchLabels.ejercicio=="p12b"' && object=$(kubectl -n p12b get pod lector -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e '([.spec.volumes[]|select(.persistentVolumeClaim.claimName=="datos")|.name]) as $vols | (any(.status.conditions[]?; .type=="Ready" and .status=="True")) and any(.spec.containers[]; .image=="busybox:1.37.0-musl" and any(.volumeMounts[]?; .mountPath=="/datos" and (.name as $name|$vols|index($name))!=null))' && test -z "$(kubectl -n p12b get pod escritor --ignore-not-found -o name)" && kubectl -n p12b exec lector -- grep -qx PERSISTENTE /datos/mensaje.txt
echo POSITIVO_c12-b
kubectl -n p12b delete pod lector --wait=true --timeout=90s
kubectl get --raw=/readyz --request-timeout=20s
if (set -eu; object=$(kubectl -n p12b get pv pv-p12b -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e 'def cantidad: ((tostring|capture("^(?<n>[-+]?(?:[0-9]+(?:[.][0-9]*)?|[.][0-9]+)(?:[eE][-+]?[0-9]+)?)(?<u>Ki|Mi|Gi|Ti|Pi|Ei|[numkKMGTPE]?)$"))//{n:"-1",u:""}) as $q | ($q.n|sub("^[+]";"")|sub("^[.]";"0.")|sub("^-[.]";"-0.")|tonumber)*({"":1,n:1e-9,u:1e-6,m:0.001,k:1000,K:1000,M:1e6,G:1e9,T:1e12,P:1e15,E:1e18,Ki:1024,Mi:1048576,Gi:1073741824,Ti:1099511627776,Pi:1125899906842624,Ei:1152921504606846976}[$q.u]); def equivale($n): ((cantidad-$n)|fabs)<=((($n|fabs)+1)*1e-12); .status.phase=="Bound" and (.spec.capacity.storage|equivale(33554432)) and .spec.persistentVolumeReclaimPolicy=="Retain" and .spec.claimRef.namespace=="p12b" and .spec.claimRef.name=="datos"' && object=$(kubectl -n p12b get pvc datos -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e 'def cantidad: ((tostring|capture("^(?<n>[-+]?(?:[0-9]+(?:[.][0-9]*)?|[.][0-9]+)(?:[eE][-+]?[0-9]+)?)(?<u>Ki|Mi|Gi|Ti|Pi|Ei|[numkKMGTPE]?)$"))//{n:"-1",u:""}) as $q | ($q.n|sub("^[+]";"")|sub("^[.]";"0.")|sub("^-[.]";"-0.")|tonumber)*({"":1,n:1e-9,u:1e-6,m:0.001,k:1000,K:1000,M:1e6,G:1e9,T:1e12,P:1e15,E:1e18,Ki:1024,Mi:1048576,Gi:1073741824,Ti:1099511627776,Pi:1125899906842624,Ei:1152921504606846976}[$q.u]); def equivale($n): ((cantidad-$n)|fabs)<=((($n|fabs)+1)*1e-12); .status.phase=="Bound" and (.spec.resources.requests.storage|equivale(16777216)) and .spec.accessModes==["ReadWriteOnce"]' && object=$(kubectl -n p12b get pvc datos -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e '.spec.volumeName=="pv-p12b" and .spec.storageClassName=="curso-manual" and .spec.selector.matchLabels.ejercicio=="p12b"' && object=$(kubectl -n p12b get pod lector -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e '([.spec.volumes[]|select(.persistentVolumeClaim.claimName=="datos")|.name]) as $vols | (any(.status.conditions[]?; .type=="Ready" and .status=="True")) and any(.spec.containers[]; .image=="busybox:1.37.0-musl" and any(.volumeMounts[]?; .mountPath=="/datos" and (.name as $name|$vols|index($name))!=null))' && test -z "$(kubectl -n p12b get pod escritor --ignore-not-found -o name)" && kubectl -n p12b exec lector -- grep -qx PERSISTENTE /datos/mensaje.txt); then echo ERROR_ACEPTO_INCOMPLETO; exit 1; fi
echo NEGATIVO_c12-b
kubectl delete namespace p12b --ignore-not-found --wait=true --timeout=120s
kubectl delete pv pv-p12b --ignore-not-found --wait=true --timeout=90s
rm -f /root/p12b-pv.yaml
fi
if test "${1:-all}" = all || test "${1:-all}" = c12-c; then
echo INICIO_c12-c
kubectl get --raw=/readyz --request-timeout=20s
kubectl wait --for=condition=Ready node/cka-w1 --timeout=120s
test -z "$(kubectl get namespace p12c --ignore-not-found -o name)"
kubectl create namespace p12c
kubectl -n p12c wait --for=create serviceaccount/default --timeout=90s
test -z "$(kubectl get sc curso-dinamica --ignore-not-found -o name)"
printf '%s\n' '{"apiVersion":"storage.k8s.io/v1","kind":"StorageClass","metadata":{"name":"curso-dinamica"},"provisioner":"rancher.io/local-path","reclaimPolicy":"Retain","volumeBindingMode":"WaitForFirstConsumer"}' | kubectl apply -f -
printf '%s\n' '{"apiVersion":"v1","kind":"PersistentVolumeClaim","metadata":{"name":"datos","namespace":"p12c"},"spec":{"storageClassName":"curso-dinamica","accessModes":["ReadWriteOnce"],"resources":{"requests":{"storage":"16Mi"}}}}' | kubectl apply -f -
kubectl -n p12c get pvc
printf '%s\n' '{"apiVersion":"v1","kind":"Pod","metadata":{"name":"cliente","namespace":"p12c","labels":{"app":"cliente"}},"spec":{"terminationGracePeriodSeconds":1,"containers":[{"name":"app","image":"busybox:1.37.0-musl","imagePullPolicy":"Never","command":["sleep","3600"],"volumeMounts":[{"name":"datos","mountPath":"/datos"}]}],"volumes":[{"name":"datos","persistentVolumeClaim":{"claimName":"datos"}}]}}' | kubectl apply -f -
kubectl -n p12c wait --for=condition=Ready pod/cliente --timeout=180s
kubectl -n p12c exec cliente -- sh -c 'echo DINAMICO > /datos/mensaje.txt'
kubectl -n p12c get pvc
kubectl get pv
object=$(kubectl -n p12c get storageclass curso-dinamica -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e '.provisioner=="rancher.io/local-path" and .reclaimPolicy=="Retain" and .volumeBindingMode=="WaitForFirstConsumer" and (.metadata.annotations["storageclass.kubernetes.io/is-default-class"]//"false")!="true"' && object=$(kubectl -n p12c get pvc datos -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e 'def cantidad: ((tostring|capture("^(?<n>[-+]?(?:[0-9]+(?:[.][0-9]*)?|[.][0-9]+)(?:[eE][-+]?[0-9]+)?)(?<u>Ki|Mi|Gi|Ti|Pi|Ei|[numkKMGTPE]?)$"))//{n:"-1",u:""}) as $q | ($q.n|sub("^[+]";"")|sub("^[.]";"0.")|sub("^-[.]";"-0.")|tonumber)*({"":1,n:1e-9,u:1e-6,m:0.001,k:1000,K:1000,M:1e6,G:1e9,T:1e12,P:1e15,E:1e18,Ki:1024,Mi:1048576,Gi:1073741824,Ti:1099511627776,Pi:1125899906842624,Ei:1152921504606846976}[$q.u]); def equivale($n): ((cantidad-$n)|fabs)<=((($n|fabs)+1)*1e-12); .status.phase=="Bound" and (.spec.resources.requests.storage|equivale(16777216)) and .spec.accessModes==["ReadWriteOnce"]' && object=$(kubectl -n p12c get pvc datos -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e '.spec.storageClassName=="curso-dinamica" and .spec.selector==null' && pv=$(kubectl -n p12c get pvc datos -o jsonpath='{.spec.volumeName}') && test -n "$pv" && object=$(kubectl get pv "$pv" -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e '.metadata.annotations["pv.kubernetes.io/provisioned-by"]=="rancher.io/local-path" and .spec.persistentVolumeReclaimPolicy=="Retain"' && object=$(kubectl -n p12c get pod cliente -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e '([.spec.volumes[]|select(.persistentVolumeClaim.claimName=="datos")|.name]) as $vols | (any(.status.conditions[]?; .type=="Ready" and .status=="True")) and any(.spec.containers[]; .image=="busybox:1.37.0-musl" and any(.volumeMounts[]?; .mountPath=="/datos" and (.name as $name|$vols|index($name))!=null))' && kubectl -n p12c exec cliente -- grep -qx DINAMICO /datos/mensaje.txt
echo POSITIVO_c12-c
kubectl -n p12c delete pod cliente --wait=true --timeout=90s
kubectl get --raw=/readyz --request-timeout=20s
if (set -eu; object=$(kubectl -n p12c get storageclass curso-dinamica -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e '.provisioner=="rancher.io/local-path" and .reclaimPolicy=="Retain" and .volumeBindingMode=="WaitForFirstConsumer" and (.metadata.annotations["storageclass.kubernetes.io/is-default-class"]//"false")!="true"' && object=$(kubectl -n p12c get pvc datos -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e 'def cantidad: ((tostring|capture("^(?<n>[-+]?(?:[0-9]+(?:[.][0-9]*)?|[.][0-9]+)(?:[eE][-+]?[0-9]+)?)(?<u>Ki|Mi|Gi|Ti|Pi|Ei|[numkKMGTPE]?)$"))//{n:"-1",u:""}) as $q | ($q.n|sub("^[+]";"")|sub("^[.]";"0.")|sub("^-[.]";"-0.")|tonumber)*({"":1,n:1e-9,u:1e-6,m:0.001,k:1000,K:1000,M:1e6,G:1e9,T:1e12,P:1e15,E:1e18,Ki:1024,Mi:1048576,Gi:1073741824,Ti:1099511627776,Pi:1125899906842624,Ei:1152921504606846976}[$q.u]); def equivale($n): ((cantidad-$n)|fabs)<=((($n|fabs)+1)*1e-12); .status.phase=="Bound" and (.spec.resources.requests.storage|equivale(16777216)) and .spec.accessModes==["ReadWriteOnce"]' && object=$(kubectl -n p12c get pvc datos -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e '.spec.storageClassName=="curso-dinamica" and .spec.selector==null' && pv=$(kubectl -n p12c get pvc datos -o jsonpath='{.spec.volumeName}') && test -n "$pv" && object=$(kubectl get pv "$pv" -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e '.metadata.annotations["pv.kubernetes.io/provisioned-by"]=="rancher.io/local-path" and .spec.persistentVolumeReclaimPolicy=="Retain"' && object=$(kubectl -n p12c get pod cliente -o json) && test -n "$object" && printf '%s\n' "$object" | jq -e '([.spec.volumes[]|select(.persistentVolumeClaim.claimName=="datos")|.name]) as $vols | (any(.status.conditions[]?; .type=="Ready" and .status=="True")) and any(.spec.containers[]; .image=="busybox:1.37.0-musl" and any(.volumeMounts[]?; .mountPath=="/datos" and (.name as $name|$vols|index($name))!=null))' && kubectl -n p12c exec cliente -- grep -qx DINAMICO /datos/mensaje.txt); then echo ERROR_ACEPTO_INCOMPLETO; exit 1; fi
echo NEGATIVO_c12-c
kubectl delete namespace p12c --ignore-not-found --wait=true --timeout=120s
